mapper.sql:
SELECT A.*,J.TITLE JOB_TITLE,C.COMPANY_NAME FROM AI_ANALYSIS A JOIN JOB_POSTING J
        ON J.JOB_ID=A.JOB_ID LEFT JOIN COMPANY C ON C.COMPANY_ID=J.COMPANY_ID WHERE
        A.MEMBER_ID=#{memberId}

mapper.insert:
/* id="insertAnalysis" */

    SELECT  AI_ANALYSIS_SEQ.NEXTVAL
    FROM    DUAL

INSERT INTO AI_ANALYSIS (
    ANALYSIS_ID
   ,MEMBER_ID
   ,JOB_ID
   ,STATUS
   ,REQUESTED_AT
) VALUES (
    #{analysisId}
   ,#{memberId}
   ,#{jobId}
   ,#{status}
   ,SYSTIMESTAMP
)

mapper.update:
/* id="completeAnalysis" */
UPDATE  AI_ANALYSIS
SET     STATUS                = #{status}
       ,SUMMARY               = #{summary,jdbcType=CLOB}
       ,MAIN_TASKS            = #{mainTasks,jdbcType=CLOB}
       ,QUALIFICATIONS        = #{qualifications,jdbcType=CLOB}
       ,PREFERENCES           = #{preferences,jdbcType=CLOB}
       ,REQUIRED_COMPETENCIES = #{requiredCompetencies,jdbcType=CLOB}
       ,RAW_RESPONSE          = #{rawResponse,jdbcType=CLOB}
       ,ERROR_MESSAGE         = #{errorMessage,jdbcType=VARCHAR}
       ,MODEL_NAME            = #{modelName,jdbcType=VARCHAR}
       ,COMPLETED_AT          = SYSTIMESTAMP
WHERE   ANALYSIS_ID = #{analysisId}

/* id="failAnalysis" */
UPDATE  AI_ANALYSIS
SET     STATUS        = 'FAILED'
       ,ERROR_MESSAGE = #{errorMessage,jdbcType=VARCHAR}
       ,COMPLETED_AT  = SYSTIMESTAMP
WHERE   ANALYSIS_ID = #{analysisId}

