mapper.delete:
/* id="deleteRecommendations" */
DELETE
FROM    AI_EXPERIENCE_RECOMMEND
WHERE   ANALYSIS_ID = #{analysisId}

/* [추가] 회원 소유권을 함께 확인하여 본인의 AI 분석 결과만 삭제합니다. */
DELETE
FROM    AI_ANALYSIS
WHERE   MEMBER_ID = #{memberId}
AND     ANALYSIS_ID = #{analysisId}

mapper.insert:
/* id="insertRecommendation" */

SELECT  AI_EXPERIENCE_RECOMMEND_SEQ.NEXTVAL
FROM    DUAL

INSERT INTO AI_EXPERIENCE_RECOMMEND (
    RECOMMEND_ID
   ,ANALYSIS_ID
   ,PROJECT_ID
   ,RANK_NO
   ,REASON
   ,SOURCE_DETAIL
   ,SAVED_YN
   ,CREATED_AT
) VALUES (
    #{recommendId}
   ,#{analysisId}
   ,#{projectId,jdbcType=NUMERIC}
   ,#{rankNo}
   ,#{reason,jdbcType=CLOB}
   ,#{sourceDetail,jdbcType=CLOB}
   ,#{savedYn}
   ,SYSTIMESTAMP
)

mapper.update:
/* [수정] 로그인 회원이 소유한 분석 결과의 추천만 저장 상태를 변경합니다. */
UPDATE  AI_EXPERIENCE_RECOMMEND
SET     SAVED_YN = #{savedYn}
WHERE   RECOMMEND_ID = #{recommendId}
AND     EXISTS (
            SELECT  1
            FROM    AI_ANALYSIS A
            WHERE   A.ANALYSIS_ID = AI_EXPERIENCE_RECOMMEND.ANALYSIS_ID
            AND     A.MEMBER_ID = #{memberId}
        )

mapper.select:
/* id="selectProjectTechs" */
SELECT  T.TECH_NAME
FROM    PROJECT_TECH P
JOIN    TECH_STACK T
    ON  T.TECH_ID = P.TECH_ID
WHERE   P.PROJECT_ID = #{projectId}
